import { SOURCE_LANGUAGE } from '@supershop/shared';

/**
 * The messages a shop starts with (P4.5). English is authored here; Arabic is generated by the
 * usual pipeline, so nobody hand-writes a second version (§5.7). Staff may reword or switch any
 * of these off in Settings → Notifications; they cannot be deleted, because the sender names them.
 *
 * Variables are `{{dotted.paths}}` — the same shape the translation pipeline already protects.
 */
export const TEMPLATE_VARIABLES = Object.freeze({
  order: [
    'store.name',
    'order.number',
    'order.total',
    'order.status',
    'customer.name',
    'order.trackUrl',
  ],
  shipment: [
    'store.name',
    'order.number',
    'shipment.carrier',
    'shipment.trackingNumber',
    'order.trackUrl',
  ],
  auth: ['store.name', 'customer.name', 'link'],
});

