/** A seeded template, in the shape the collection stores. */
export const toSeed = (t) => ({
  ...t,
  subject: { [SOURCE_LANGUAGE]: t.subject },
  body: { [SOURCE_LANGUAGE]: t.body },
  enabled: true,
  builtIn: true,
});
